inputs.script:
const { recordId } = input.config();

if (!recordId) {
  throw new Error("Missing Airtable record ID");
}

const response = await fetch(
  "https://n8n.dulcy.io/webhook/REDACTED_PATH",
  {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      secret: "REDACTED_SECRET",
      recordId: recordId
    })
  }
);

const responseText = await response.text();

if (!response.ok) {
  throw new Error(
    `n8n webhook failed: ${response.status} ${responseText}`
  );
}

output.set("recordId", recordId);
output.set("n8nResponse", responseText);
